import re,csv
data=open(GRAPH_TTL).read()
labels=dict(re.findall(r'bldg:(\w+)\s+a\s+brick:\w+\s*;\s*\n\s*rdfs:label\s+"([^"]+)"', data))
blocks=data.split('\n\n')
mapping=[]
for b in blocks:
    if 'a brick:Zone_Air_Temperature_Sensor' in b:
        subj=b.split()[0].split('#')[-1]
        me=re.search(r'hasExternalReference\s+<urn:buildgraph:tsref:([\w-]+)>', b)
        mz=re.search(r'isPointOf bldg:(\w+)', b)
        z=mz.group(1) if mz else None
        name=labels.get(z)
        if me: mapping.append((name, me.group(1), z))
TS='2018-04-23T12:00:00'
target=set(t for _,t,_ in mapping)
vals={}
with open(VALUES_CSV) as f:
    r=csv.reader(f); next(r)
    for row in r:
        if row[1]==TS and row[0] in target:
            vals[row[0]]=float(row[2])
res=[]
for name,t,z in mapping:
    if t in vals: res.append((name, vals[t], z))
res.sort(key=lambda x:-x[1])
for x in res: print(x)
print('MAX:', res[0] if res else None)
